/** Articles: the posts of the row on the page */
function AuthorPostsSection({ id, user }: { id: ReturnType<typeof idOf>; user: SessionUser | null }) {
  const [page, setPage] = useState(1);
  const router = useRouter();
  const opens = user !== null;
  const input = { page, page_size: 10, sort: "posted_at:desc", author_id: id, published: "true" } as Inputs["posts"]["list"];
  const list = useQuery({ queryKey: ["posts", "list", input], queryFn: () => client.posts.list(input) });
  const status = errorStatus(list.error);
  if (status === 401 || status === 403) return null;
  return (
    <section className="mt-8 space-y-3">
      <h2 className="text-sm font-semibold">
        {"Articles"}
        {list.data ? <span className="ml-2 font-normal text-muted-foreground">{list.data.page.total}</span> : null}
      </h2>
      {list.isPending ? (
        <ListSkeleton />
      ) : list.error ? (
        <ErrorNote error={list.error} />
      ) : list.data.data.length === 0 ? (
        <p className="text-sm text-muted-foreground">No articles yet.</p>
      ) : (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Title</TableHead>
              <TableHead>Posted At</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {list.data.data.map((row) => (
              <TableRow key={text(row.id)} className={opens ? "cursor-pointer" : undefined} onClick={opens ? () => router.push(`/posts/${text(row.id)}`) : undefined}>
                <TableCell>{text(row.title)}</TableCell>
                <TableCell>{formatDateTime(row.posted_at)}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}
      {list.data ? <Pagination page={page} pageSize={10} total={list.data.page.total} onChange={setPage} /> : null}
    </section>
  );
}

export function AuthorPage() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.users.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["users"]["update"]) => client.users.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const banAction = useMutation({
    mutationFn: (input: Inputs["users"]["ban"]) => client.users.ban(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} signIn={<Link href="/login" className={buttonVariants()}>Sign in</Link>} />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "User " + text(row.id)}
      actions={
        <>
          {canBan(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setOpenAction(open => (open === "ban" ? null : "ban"))}>
              Ban
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
        </>
      }
    >
      {openAction === "ban" ? (
        <div className="mb-6 rounded-md border border-border p-4">
          <AuthorBanForm fields={AUTHORBAN_CREATE} initial={EMPTY_AUTHORBAN} submitLabel="Ban" pending={banAction.isPending} error={banAction.error} onCancel={() => setOpenAction(null)} onSubmit={values => banAction.mutate({ id, ...toAuthorBanCreateInput(values) })} />
        </div>
      ) : null}

      {editing ? (
        <AuthorForm
          fields={offeredAuthor(AUTHOR_UPDATE, field => field in row)}
          initial={authorFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: sentAuthor(toAuthorUpdateInput(values), field => field in row) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        </dl>
      )}
      <AuthorPostsSection key={text(row.id)} id={id} user={user} />
    </Pane>
  );
}
